import { useMemo, useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxField,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxStack,
  JxSwitch,
} from '@jinx-ui/react';

type Role = 'admin' | 'editor' | 'viewer';

const ROLES: { value: Role; label: string }[] = [
  { value: 'admin', label: 'Администратор' },
  { value: 'editor', label: 'Редактор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = useMemo(() => EMAIL_PATTERN.test(email.trim()), [email]);
  const showError = touched && !isValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-4)">
      {invitedEmail && (
        <JxAlert
          variant="success"
          title="Приглашение отправлено"
          dismissible
          onDismiss={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ к команде.
        </JxAlert>
      )}

      <form onSubmit={handleSubmit} noValidate>
        <JxStack direction="column" gap="var(--jx-space-4)">
          <JxField
            label="Рабочая почта"
            hint="Пригласим по адресу компании, личные ящики лучше не использовать."
            error={showError ? 'Введите адрес в формате name@company.com' : undefined}
          >
            <JxInput
              type="email"
              name="email"
              placeholder="name@company.com"
              autoComplete="email"
              value={email}
              onValueChange={setEmail}
              onBlur={() => setTouched(true)}
              invalid={showError}
            />
          </JxField>

          <JxField label="Роль в команде">
            <JxSelect
              name="role"
              value={role}
              onValueChange={(next: Role) => setRole(next)}
            >
              {ROLES.map((item) => (
                <JxSelectOption key={item.value} value={item.value}>
                  {item.label}
                </JxSelectOption>
              ))}
            </JxSelect>
          </JxField>

          <JxSwitch
            name="notify"
            label="Отправить уведомление"
            checked={notify}
            onCheckedChange={setNotify}
          />

          <JxButton type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </JxButton>
        </JxStack>
      </form>
    </JxStack>
  );
}

